(function() {
	//#region src/Themes/CrestApps.OrchardCore.AdminTheme/Assets/js/color-scheme-editor.js
	var form = document.querySelector("[data-color-scheme-editor]");
	if (form) {
		const previewUrl = form.dataset.previewUrl;
		const style = document.createElement("style");
		document.head.appendChild(style);
		const hexPattern = /^#[0-9a-f]{6}$/i;
		let timer = 0;
		let request = 0;
		const refresh = async () => {
			const query = new URLSearchParams();
			for (const [name, value] of new FormData(form)) if (name !== "__RequestVerificationToken") query.append(name, value);
			const current = ++request;
			const response = await fetch(`${previewUrl}?${query}`, { credentials: "same-origin" });
			if (response.ok && current === request) style.textContent = await response.text();
		};
		const schedule = () => {
			window.clearTimeout(timer);
			timer = window.setTimeout(refresh, 200);
		};
		form.querySelectorAll("[data-color-picker]").forEach((picker) => {
			const hex = form.querySelector(`[data-color-hex="${picker.dataset.colorPicker}"]`);
			picker.addEventListener("input", () => {
				hex.value = picker.value;
				schedule();
			});
			hex.addEventListener("input", () => {
				if (hexPattern.test(hex.value.trim())) picker.value = hex.value.trim().toLowerCase();
			});
		});
		form.addEventListener("input", schedule);
		form.addEventListener("change", schedule);
		refresh();
	}
	//#endregion
})();
